    /// A mark made while the job runs must not cost the Chunk its mesh, and must still produce
    /// the fresh one.
    #[test]
    fn a_chunk_dirtied_in_flight_is_delivered_and_meshed_again() {
        let mut h = harness();
        h.app.world_mut().resource_mut::<LodJobs>().mesh.hold.hold();
        let shells = all_shells(&h).len();
        let started = std::time::Instant::now();
        while h.lod_jobs().mesh.in_flight() < shells {
            assert!(
                started.elapsed() < SETTLE_CEILING,
                "meshes never dispatched"
            );
            h.lod_tick();
            std::thread::sleep(std::time::Duration::from_micros(100));
        }

        let marked = ChunkCoord::new(0, 0, 0);
        h.app
            .world_mut()
            .resource_mut::<LodState>()
            .level_mut(1)
            .dirty
            .insert(marked, LodCause::Edit);
        let gate = Arc::clone(&h.lod_jobs().mesh.hold);
        gate.release();
        // Closed again once the first meshes are done and before a tick can dispatch the fresh
        // one, so the fresh mesh lands after the stale one is sent: a mesh still withheld when
        // its replacement lands is replaced unsent, which timing alone would otherwise decide.
        let started = std::time::Instant::now();
        loop {
            let mut jobs = h.app.world_mut().resource_mut::<LodJobs>();
            jobs.mesh.poll();
            if jobs.mesh.finished().count() == shells {
                break;
            }
            assert!(started.elapsed() < SETTLE_CEILING, "meshes never finished");
            std::thread::sleep(std::time::Duration::from_micros(100));
        }
        gate.hold();
        let mut ready = Vec::new();
        while !h.delivered_at(1).contains(&marked) {
            assert!(
                started.elapsed() < SETTLE_CEILING,
                "the stale mesh was never sent"
            );
            ready.extend(h.lod_tick().0);
        }
        gate.release();
        ready.extend(h.lod_settle().0);

        let count = |c: ChunkCoord| {
            ready
                .iter()
                .filter(|m| (m.level, m.coord) == (1, c))
                .count()
        };
        assert_eq!(count(marked), 2, "delivered once, then again");
        assert_eq!(count(ChunkCoord::new(1, 0, 0)), 1);
        assert!(h.delivered_at(1).contains(&marked));
        assert!(h.lod_jobs().mesh.stale() > 0);
    }

    /// A hole with room for a hysteresis around it: level 0 is six Cells across and two high, so
    /// level 1 has a hole of one Cell and a keep hole of none.
    fn hole_settings() -> StreamingSettings {
        StreamingSettings {
            view_distance_m: 192.0,
            vertical_distance_m: 64.0,
            hysteresis_m: 32.0,
            lod_distance_m: 384.0,
            lod_unit_m: 0.0,
        }
    }

    fn d(x: i32, y: i32, z: i32) -> IVec3 {
        IVec3::new(x, y, z)
    }

    #[test]
    fn the_hole_is_not_meshed_and_the_overlap_around_it_is() {
        let mut h = harness_with(hole_settings(), unlimited());
        let rings = h.rings_of(1);
        assert_eq!(
            rings.mesh.hole.map(|e| (e.horizontal, e.vertical)),
            Some((1, 0))
        );
        let (ready, _) = h.lod_settle();
        let anchor = h.anchor_of(1);
        let coord_at = |delta: IVec3| offset(anchor, delta);

        let delivered = h.delivered_at(1);
        for delta in [d(0, 0, 0), d(1, 0, 0), d(0, 0, -1)] {
            assert!(
                !delivered.contains(&coord_at(delta)),
                "{delta} is in the hole"
            );
        }
        // The overlap: inside what level 0 covers (3 Cells here, so up to 6 of level 1's across)
        // and outside the hole.
        for delta in [d(1, 0, 1), d(2, 0, 1), d(3, 0, 0), d(0, 1, 0), d(0, -1, 2)] {
            assert!(
                delivered.contains(&coord_at(delta)),
                "{delta} is the overlap"
            );
        }
        let expected: HashSet<ChunkCoord> = h
            .mesh_shell(1)
            .into_iter()
            .filter(|&c| !rings.mesh.hole.unwrap().contains(delta(anchor, c)))
            .collect();
        assert_eq!(delivered, expected);
        assert_eq!(latest(ready).len(), expected.len());
    }

    #[test]
    fn walking_onto_a_coarse_chunk_releases_it_only_past_the_hysteresis() {
        let mut h = harness_with(hole_settings(), unlimited());
        h.lod_settle();
        let cell = h.app.world().resource::<WorldSettings>().cell_size_at(1);
        let target = ChunkCoord::new(2, 0, 0);
        assert!(h.delivered_at(1).contains(&target));

        // One Cell away: inside the mesh hole, but still inside keep's.
        h.anchor_at(Vec3::new(cell, 0.0, 0.0));
        let (_, unloaded) = h.lod_tick();
        assert!(
            !unloaded.iter().any(|u| (u.level, u.coord) == (1, target)),
            "released inside the hysteresis"
        );
        assert!(h.delivered_at(1).contains(&target));
        h.lod_settle();
        assert!(h.delivered_at(1).contains(&target));

        h.anchor_at(Vec3::new(2.0 * cell, 0.0, 0.0));
        let (_, unloaded) = h.lod_tick();
        assert!(
            unloaded.iter().any(|u| (u.level, u.coord) == (1, target)),
            "kept past the hysteresis"
        );
        h.lod_settle();
        assert!(!h.delivered_at(1).contains(&target));

        h.anchor_at(Vec3::ZERO);
        let (ready, _) = h.lod_settle();
        assert!(ready.iter().any(|m| (m.level, m.coord) == (1, target)));
        assert!(h.delivered_at(1).contains(&target));
    }

    /// Fills the 2x2x2 Voxels at `local` with stone by a Mod's Command.
    fn fill_by_command(h: &mut Harness, chunk: ChunkCoord, local: [i32; 3]) {
        use tesserae_mods::{Command, Region};
        let side = CHUNK_SIZE as i32;
        let min = [
            chunk.x * side + local[0],
            chunk.y * side + local[1],
            chunk.z * side + local[2],
        ];
        let size = h.app.world().resource::<WorldSettings>().voxel_size;
        let command = Command::Fill {
            region: Region {
                min: min.map(|i| i as f32 * size),
                max: min.map(|i| (i + 2) as f32 * size),
            },
            voxel: stone(),
        };
        crate::server::mods::runtime::tests::drain_validated(
            &mut h.app,
            tesserae_mods::Line::V02,
            &[command],
        );
    }

    #[test]
    fn a_mod_fill_invalidates_a_held_level_one_cover_and_redelivers_its_mesh() {
        let mut h = harness();
        h.settle();
        h.lod_settle();
        let chunk = h.quiet_chunk();
        let covering = chunk.parent();
        let before = h.cover_arc(covering);
        fill_by_command(&mut h, chunk, [10, 10, 10]);
        let (ready, _) = h.lod_settle();
        assert!(!same_chunk(&before, &h.cover_arc(covering)));
        assert!(same_chunk(
            &h.cover_arc(covering),
            &expected_cover(&h, chunk)
        ));
        let delivered = latest(ready);
        assert!(same_mesh(
            delivered.get(&(1, covering)).expect("cover redelivered"),
            &h.fresh_mesh(1, covering)
        ));
        assert!(!h.lod_state().is_stale(1, covering));
    }

